CREATE TABLE `oauth_states` (`state` text PRIMARY KEY NOT NULL, `owner` text NOT NULL, `provider` text NOT NULL, `code_verifier` text NOT NULL, `expires` integer NOT NULL, FOREIGN KEY (`owner`) REFERENCES `accounts`(`owner`) ON DELETE CASCADE);--> statement-breakpoint
CREATE TABLE `source_syncs` (`owner` text PRIMARY KEY NOT NULL, `youtube_status` text NOT NULL DEFAULT 'never', `youtube_summary` text NOT NULL DEFAULT '', `youtube_updated` text, `linkedin_status` text NOT NULL DEFAULT 'never', `linkedin_summary` text NOT NULL DEFAULT '', `linkedin_updated` text, `updated` text NOT NULL, FOREIGN KEY (`owner`) REFERENCES `accounts`(`owner`) ON DELETE CASCADE);
